where p.del_flag = '0'


        and p.tenant_id = #{bo.tenantId}


        and t.company_name like concat('%', #{bo.tenantName}, '%')


        and p.product_code = #{bo.productCode}


        and p.product_name like concat('%', #{bo.productName}, '%')


        and p.policy_no = #{bo.policyNo}


        and p.order_no = #{bo.orderNo}


        and p.agent_name like concat('%', #{bo.agentName}, '%')


        and p.premium = #{bo.premium}


        and p.amt = #{bo.amt}


        and p.commission_status = #{bo.commissionStatus}


        and p.status = #{bo.status}


        and p.appnt_date = #{bo.appntDate}


        and p.applicant_name like concat('%', #{bo.applicantName}, '%')
